template:
@php
    $shown = array_values(array_filter(is_array($pictures) ? $pictures : [], static fn ($picture): bool => is_array($picture) && ! empty($picture['url'])));
    $sized = $shown[0] ?? null;
    $bare = $shown[1] ?? null;
@endphp
<section class="b-showcase-lightbox" data-wx-block="showcase-lightbox">
    @if ($heading)
        <h2 class="b-showcase-lightbox__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-lightbox__note">{{ $note }}</p>
    @endif
    <div class="b-showcase-lightbox__row">
        @if ($sized)
            <a class="b-showcase-lightbox__link" href="{{ $sized['url'] }}" data-webx-lightbox="" data-width="{{ $sized['width'] }}" data-height="{{ $sized['height'] }}"><img class="b-showcase-lightbox__photo" src="{{ $sized['url'] }}" width="{{ $sized['width'] }}" height="{{ $sized['height'] }}" alt="{{ $sized['alt'] ?: 'A link with its sizes' }}"></a>
        @endif
        @if ($bare)
            <a class="b-showcase-lightbox__link" href="{{ $bare['url'] }}" data-webx-lightbox=""><img class="b-showcase-lightbox__photo" src="{{ $bare['url'] }}" width="{{ $bare['width'] }}" height="{{ $bare['height'] }}" alt="{{ $bare['alt'] ?: 'A link without sizes' }}"></a>
        @endif
    </div>
</section>

styles:
.b-showcase-lightbox {
    max-width: var(--site-container-width);
